Source: https://github.com/thunderbird/thunderbird-desktop/blob/0b93f0f7a926ed94c8a0646f18b6734ec7cc0f6d/mail/base/content/widgets/attachment-list.mjs#L13
13:  * The MozAttachmentlist widget lists attachments for a mail. This is typically used to show
14:  * attachments while writing a new mail as well as when reading mails.
15:  *
16:  * @augments {MozElements.RichListBox}
17:  */
18: class MozAttachmentlist extends MozElements.RichListBox {
19:   constructor() {
20:     super();
21: 
22:     this.messenger = Cc["@mozilla.org/messenger;1"].createInstance(
23:       Ci.nsIMessenger
24:     );
25: 
26:     this.addEventListener("keypress", event => {
27:       if (event.key == " " && !event.shiftKey && !event.ctrlKey) {
28:         // Allow plain spacebar to select the focused item.
29:         this.addItemToSelection(this.currentItem);
30:         this.dispatchEvent(
31:           new CustomEvent("quicklook", {
32:             bubbles: true,
33:             detail: { index: this.getIndexOfItem(this.currentItem) },
34:           })
35:         );
36:         // Prevent inbuilt scrolling.
37:         event.preventDefault();
38:       }
39:     });
40: 
41:     // Make sure we keep the focus.
42:     this.addEventListener("mousedown", event => {
43:       if (event.button != 0) {
44:         return;
45:       }
46: 
47:       if (document.commandDispatcher.focusedElement != this) {
48:         this.focus();
49:       }
50:     });
51:   }
52: 
53:   connectedCallback() {
54:     super.connectedCallback();
55:     if (this.delayConnectedCallback()) {
56:       return;
57:     }
58: 
59:     const children = Array.from(this._childNodes);
60: 
61:     children
62:       .filter(child => child.hasAttribute("selected"))
63:       .forEach(this.selectedItems.append, this.selectedItems);
64: 
65:     children
66:       .filter(child => !child.hasAttribute("context"))
67:       .forEach(child =>
68:         child.setAttribute("context", this.getAttribute("itemcontext"))
69:       );
70: 
71:     this.addEventListener("keydown", event => {
72:       if (
73:         event.key == "Enter" &&
74:         !event.ctrlKey &&
75:         !event.altKey &&
76:         !event.metaKey &&
77:         !event.shiftKey
78:       ) {
79:         goDoCommand("cmd_openAttachment");
80:       }
81:     });
82:   }
