189:   insertItemAt(index, attachment, attachmentName) {
190:     const item = this.ownerDocument.createXULElement("richlistitem");
191:     item.classList.add("attachmentItem");
192:     item.setAttribute("role", "option");
193: 
194:     item.addEventListener("dblclick", () => goDoCommand("cmd_openAttachment"));
195: 
196:     const makeDropIndicator = placementClass => {
197:       const img = document.createElement("img", { is: "drop-indicator" });
198:       img.classList.add("attach-drop-indicator", placementClass);
199:       return img;
200:     };
201: 
202:     item.appendChild(makeDropIndicator("before"));
203: 
204:     const icon = this.ownerDocument.createElement("img");
205:     icon.setAttribute("alt", "");
206:     icon.setAttribute("draggable", "false");
207:     // Allow the src to be invalid.
208:     icon.classList.add("attachmentcell-icon", "invisible-on-broken");
209:     item.appendChild(icon);
210: 
211:     const textLabel = this.ownerDocument.createElement("span");
212:     textLabel.classList.add("attachmentcell-name");
213:     item.appendChild(textLabel);
214: 
215:     const extensionLabel = this.ownerDocument.createElement("span");
216:     extensionLabel.classList.add("attachmentcell-extension");
217:     item.appendChild(extensionLabel);
218: 
219:     const sizeLabel = this.ownerDocument.createElement("span");
220:     sizeLabel.setAttribute("role", "note");
221:     sizeLabel.classList.add("attachmentcell-size");
222:     item.appendChild(sizeLabel);
223: 
224:     item.appendChild(makeDropIndicator("after"));
225: 
226:     item.setAttribute("context", this.getAttribute("itemcontext"));
227: 
228:     item.attachment = attachment;
229:     this.invalidateItem(item, attachmentName);

