335:   /**
336:    * Set the attachment item's displayed name.
337:    *
338:    * @param {MozRichlistitem} item - The attachment item.
339:    * @param {string} attachmentName - The name to display for the attachment.
340:    */
341:   setAttachmentName(item, attachmentName) {
342:     item.setAttribute("name", attachmentName);
343:     // Extract what looks like the file extension so we can always show it,
344:     // even if the full name would overflow.
345:     // NOTE: This is a convenience feature rather than a security feature
346:     // since the content type of an attachment need not match the extension.
347:     const found = attachmentName.match(/^(.+)(\.[a-zA-Z0-9_#$!~+-]{1,16})$/);
348:     item.querySelector(".attachmentcell-name").textContent =
349:       found?.[1] || attachmentName;
350:     item.querySelector(".attachmentcell-extension").textContent =
351:       found?.[2] || "";
352:   }
353: 
354:   /**
355:    * Set the attachment item's displayed size.
356:    *
357:    * @param {MozRichlistitem} item - The attachment item.
358:    * @param {string} size - The size to display for the attachment.
359:    */
360:   setAttachmentSize(item, size) {
361:     item.setAttribute("size", size);
362:     const sizeEl = item.querySelector(".attachmentcell-size");
363:     sizeEl.textContent = size;
364:     sizeEl.hidden = !size;
365:   }
366: 
367:   invalidateItem(item, attachmentName) {
368:     const attachment = item.attachment;
369: 
370:     this.setAttachmentName(item, attachmentName || attachment.name);
371:     let size =
372:       attachment.size == null || attachment.size == -1
373:         ? ""
374:         : this.messenger.formatFileSize(attachment.size);
375:     if (size && item.cloudHtmlFileSize > 0) {
376:       size = `${this.messenger.formatFileSize(
377:         item.cloudHtmlFileSize
378:       )} (${size})`;
379:     }
380:     this.setAttachmentSize(item, size);
381: 
382:     // By default, items are considered loaded.
383:     item.loaded = true;
384:     this.refreshAttachmentIcon(item);
385:     return item;
386:   }
